import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.BjY7aUvS.js";const b=JSON.parse('{"title":"溯源码查询 · 农产品与婴幼儿配方乳粉的\\"前世今生\\"","description":"扫溯源码查农产品与婴幼儿配方乳粉的官方教程：农业农村部国家追溯平台与工信部食品工业企业追溯平台。","frontmatter":{"title":"溯源码查询 · 农产品与婴幼儿配方乳粉的\\"前世今生\\"","issuer":"农业农村部 / 工业和信息化部","source_tier":"一级来源","version":"—","published":"—","source_url":"http://www.qsst.moa.gov.cn","status":"现行服务","tags":["官方查询","溯源","农产品","婴幼儿配方乳粉","防坑"],"type":"查询页","reviewed":false,"description":"扫溯源码查农产品与婴幼儿配方乳粉的官方教程：农业农村部国家追溯平台与工信部食品工业企业追溯平台。"},"headers":[],"relativePath":"query/traceability.md","filePath":"query/traceability.md"}'),d={name:"query/traceability.md"};function l(h,t,i,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="溯源码查询-·-农产品与婴幼儿配方乳粉的-前世今生" tabindex="-1">溯源码查询 · 农产品与婴幼儿配方乳粉的&quot;前世今生&quot; <a class="header-anchor" href="#溯源码查询-·-农产品与婴幼儿配方乳粉的-前世今生" aria-label="Permalink to &quot;溯源码查询 · 农产品与婴幼儿配方乳粉的&quot;前世今生&quot;&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理；农产品追溯平台入口对自动化访问返回 403（平台存在），查询请以农业农村部官网入口为准。</p></div><blockquote><p><strong>官方入口</strong>：农业农村部<a href="http://www.qsst.moa.gov.cn" target="_blank" rel="noreferrer">国家农产品质量安全追溯管理信息平台</a>（扫码查履历）；工信部<a href="https://foodcredit.miit.gov.cn" target="_blank" rel="noreferrer">食品工业企业追溯平台</a>（重点覆盖<strong>婴幼儿配方乳粉</strong>追溯）。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>带<strong>溯源二维码</strong>的农产品和婴幼儿配方乳粉，扫码就能看到产地、生产、检验、流通信息——&quot;从农田到餐桌&quot;的官方履历。给孩子买奶粉、给老人买粮油，认准可追溯的产品并顺手扫码验证。</p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>找到包装上的<strong>追溯二维码</strong>（或追溯码数字）</td></tr><tr><td>2</td><td>用微信&quot;扫一扫&quot;扫码，或到对应平台输入追溯码：农产品走<a href="http://www.qsst.moa.gov.cn" target="_blank" rel="noreferrer">国家追溯平台</a>，婴幼儿配方乳粉走<a href="https://foodcredit.miit.gov.cn" target="_blank" rel="noreferrer">工信部追溯平台</a></td></tr><tr><td>3</td><td>核对：产地/厂家、生产日期、检验信息与包装是否一致</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>履历完整且与包装一致</td><td>可追溯产品（<a href="http://www.qsst.moa.gov.cn" target="_blank" rel="noreferrer">追溯平台</a>）</td></tr><tr><td>扫码无结果或信息对不上</td><td>谨慎购买，向商家索要进货凭证</td></tr><tr><td>平台查不到但商家称&quot;有机/绿色&quot;</td><td>让商家出示认证证书编号，去认证机构官网核</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;自家散养纯天然，比可追溯的更好&quot;</td><td>无溯源无检验的无证产品风险自担，追溯体系正是官方给的验证工具</td></tr><tr><td>【本站提示】溯源码只能证明&quot;履历真实&quot;，不能替代<a href="/SageRelay/query/food-spot-check.html">抽检记录</a>——两个都查更稳</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li>抽检记录：<a href="/SageRelay/query/food-spot-check.html">食品抽检结果查询</a></li><li>生产资质：<a href="/SageRelay/query/sc-food.html">食品生产许可 SC 查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>农业农村部国家追溯平台、工信部食品工业企业追溯平台（一级来源）</td></tr><tr><td>入口</td><td><a href="http://www.qsst.moa.gov.cn" target="_blank" rel="noreferrer">qsst.moa.gov.cn</a> · <a href="https://foodcredit.miit.gov.cn" target="_blank" rel="noreferrer">foodcredit.miit.gov.cn</a>（入口以各部委官网为准）</td></tr></tbody></table>',15)])])}const q=a(d,[["render",l]]);export{b as __pageData,q as default};
